import {signalTypes,signalStatuses,signalFields,safeSource,briefReady,measuredSignals,marketBrief,updateSignal} from './market-trial-model.mjs';
export function createMarketTrial({getData,changed,esc,toast}){
 let editing=null,filter='All';
 const button=(label,action,id='')=>`<button type="button" class="secondary" data-mt="${action}" data-id="${esc(id)}">${label}</button>`;
 const labels={title:'Signal headline *',company:'Company / project alias *',type:'Signal type',url:'Original source URL (HTTPS) *',published:'Publication date *',captured:'Date captured',fact:'What does the source actually say? *',relevance:'Why might it matter to PRG? (hypothesis) *',question:'Question for the business-development call *',owner:'Responsible role *',jobadder:'JobAdder record reference (optional)',capability:'Approved capability content / reference (optional)',reviewer:'Reviewer role *',status:'Review decision',baseline:'Comparable manual preparation (minutes)',assisted:'Preparation with this workflow, including review (minutes)',outcome:'Follow-up outcome / learning'};
 function input(s,k){const opts=k==='type'?signalTypes:k==='status'?signalStatuses:null;const attrs=`data-mt-field="${k}"`;return `<label>${esc(labels[k])}${opts?`<select ${attrs}>${opts.map(o=>`<option ${s[k]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:['fact','relevance','question','capability','outcome'].includes(k)?`<textarea ${attrs} maxlength="4000" rows="3">${esc(s[k])}</textarea>`:`<input ${attrs} type="${['published','captured'].includes(k)?'date':['baseline','assisted'].includes(k)?'number':k==='url'?'url':'text'}" ${['baseline','assisted'].includes(k)?'min="0" max="10000" step="0.1"':''} maxlength="4000" value="${esc(s[k])}">`}</label>`;}
 function editor(){const s=getData().signals.find(s=>s.id===editing);return s?`<section class="ct-section mt-editor"><div class="panel-head"><h3>Capture and check a signal</h3>${button('Close editor','close')}</div><p>* Required before a brief can be exported. “Approved for brief” records your review decision; the website cannot verify a source for you.</p><div class="project-form">${signalFields.map(k=>input(s,k)).join('')}</div><div class="actions">${button('Update library','refresh')}${button('Download call brief (.txt)','brief',s.id)}</div></section>`:'';}
 function library(){const all=getData().signals,items=all.filter(s=>filter==='All'||s.type===filter),m=measuredSignals(all);return `<section class="ct-section"><h3>Signal library</h3><p>${all.length} captured · ${all.filter(briefReady).length} ready for a brief · ${m.count} paired time measurements${m.count?` · ${m.released.toFixed(1)} minutes net capacity released${m.percent===null?'':` (${m.percent}%)`}`:''}.</p><p class="panel-note">Self-reported trial measurements, not proven savings. Blank times are excluded; negative results mean extra time. Include finding, checking, drafting and correcting in both workflows.</p><label>Filter by signal type <select id="mt-filter">${['All',...signalTypes].map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select></label>${items.length?`<div class="table-wrap"><table><caption class="sr-only">Market signals and review status</caption><thead><tr><th>Signal / company</th><th>Source date</th><th>Review</th><th>Next step</th></tr></thead><tbody>${items.map(s=>`<tr><td><strong>${esc(s.title||'Untitled signal')}</strong><small>${esc(s.company||'Company not recorded')} · ${esc(s.type)}</small></td><td>${esc(s.published||'Unknown')}${safeSource(s.url)?`<br><a href="${esc(safeSource(s.url))}" target="_blank" rel="noopener noreferrer">Open source</a>`:''}</td><td><span class="pill">${esc(s.status)}</span><small>${briefReady(s)?'Brief ready':s.status==='Approved for brief'?'Complete required evidence fields':'Review before use'}</small></td><td>${button('Review / edit','edit',s.id)} ${button('Call brief','brief',s.id)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="ct-empty">No signals in this view. Add a sanitised news item, project update, role change or hiring signal to begin.</p>'}</section>`;}
 function view(){return `<section id="market-trial" class="panel ct-trial mt-trial"><div class="panel-head"><div><p class="eyebrow">TRIAL 2 / MARKET INTELLIGENCE & BUSINESS DEVELOPMENT</p><h2>Turn market updates into useful conversations</h2><p>One place to capture industry news, project updates, role changes and hiring activity, then prepare an evidence-backed call brief.</p></div><span class="pill blue">Proposed pilot · not yet run</span></div><div class="ct-steps"><span>01 · Capture once</span><span>02 · Verify relevance</span><span>03 · Prepare & follow up</span></div><div class="notice">Available now: manual signal library, review decisions, call-brief download and time measurements. Automated monitoring, AI research, LinkedIn capture and JobAdder sync are not connected. Notes stay in this tab; Download worksheet keeps the complete trial.</div><details class="ct-rules" open><summary>Trial scope, measures and responsibilities</summary><div class="project-deliverables"><div><h3>Core test: a useful daily briefing</h3><p>Proposed: 10 working days, two consultants, 10 agreed companies, 20 signals and 10 reviewed call briefs. Start from approved company/project announcements and public sources. A hiring advert or project announcement is a lead to check, not proof of recruitment demand.</p></div><div><h3>Contact capture: remove duplicate entry</h3><p>Test five permitted LinkedIn contact captures using an existing approved JobAdder tool first. Search for the person and company before creating a record. Have staff confirm identity and permitted fields. No automatic connection harvesting or scraping is part of this pilot.</p></div><div><h3>Capability documents: reuse approved content</h3><p>Test five briefs against the same approved Marketing template. Supply audience, approved service claims, relevant case studies and brand assets. Compare manual preparation with assisted drafting in an approved tool; Marketing reviews layout and every claim. This workspace exports text inputs, not a finished branded document.</p></div><div><h3>Decision gate</h3><p>Proposed targets to agree: at least 30% less preparation time, 8/10 call briefs rated useful, every brief traceable to a checked source, zero unsupported claims in approved outputs and zero duplicate contacts from the five capture tests. Report the three workstreams separately; time released is capacity, not cash savings.</p></div></div><p><strong>Before starting:</strong> nominate a Sales owner, consultant reviewers, Marketing approver and JobAdder administrator. Agree source access, target companies, templates, measurement method and costs. Use the Trial 2 plan below to record approval and results.</p><p><strong>Stop or hold:</strong> wrong identity, conflicting or stale evidence, unsupported claims, duplicate records, unapproved data access, or unacceptable review effort. Keep all external contact and record changes under staff control.</p></details><div class="actions">${button('+ Add market signal','add')}${button('Load one fictional example','example')}</div>${editor()}<div id="mt-library">${library()}</div><p class="panel-note">Use public information or aliases and sanitised references only. Never paste private contact details or confidential company documents into this public preview. A single-role-change alert does not establish permission to contact someone.</p></section>`;}
 function repaint(){const root=document.querySelector('#market-trial');if(root)root.outerHTML=view();}
 function updateLibrary(){const root=document.querySelector('#mt-library');if(root)root.innerHTML=library();}
 function add(example=false){const data=getData();if(data.signals.length>=100){toast('This worksheet supports 100 signals. Download it and start a new cohort.');return;}const s=Object.fromEntries(signalFields.map(k=>[k,'']));Object.assign(s,{id:crypto.randomUUID(),type:signalTypes[0],status:signalStatuses[0],captured:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Sydney'})});if(example)Object.assign(s,{title:'FICTIONAL: Example Energy announces a project milestone',company:'Example Energy (fictional)',type:'Project update',url:'https://example.com/',fact:'Fictional practice item only; no real announcement has been researched.',relevance:'Ask whether the next project stage changes workforce plans. Do not assume vacancies exist.',question:'What are the key delivery milestones, and where might additional expertise be needed?',owner:'Consultant',capability:'Ask Marketing for approved project-delivery capability content.'});data.signals.push(s);editing=s.id;changed();repaint();document.querySelector('[data-mt-field="title"]')?.focus();}
 document.addEventListener('input',e=>{const k=e.target.dataset.mtField,s=getData().signals.find(s=>s.id===editing);if(!s||!signalFields.includes(k))return;updateSignal(s,k,e.target.value);const decision=document.querySelector('[data-mt-field="status"]');if(decision)decision.value=s.status;changed();updateLibrary();});
 document.addEventListener('change',e=>{if(e.target.id==='mt-filter'){filter=e.target.value;updateLibrary();}});
 document.addEventListener('click',e=>{const t=e.target.closest('[data-mt]');if(!t)return;switch(t.dataset.mt){case 'add':add();break;case 'example':add(true);break;case 'close':editing=null;repaint();break;case 'refresh':updateLibrary();toast('Library updated in this tab. Download worksheet to retain it.');break;case 'edit':editing=t.dataset.id;repaint();document.querySelector('.mt-editor')?.scrollIntoView({behavior:'smooth',block:'start'});break;case 'brief':{const s=getData().signals.find(s=>s.id===t.dataset.id);try{const text=marketBrief(s),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='prg-market-call-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Call brief downloaded for review. Nothing was sent or synced to JobAdder.');}catch(err){toast(err.message);}break;}}});
 return {view,reset(){editing=null;filter='All';}};
}
